-- Drift reconciliation for Input Governance source discovery inventory.
-- Captures the exact live state introduced directly through MCP on 2026-09-30.
-- No new runtime semantics are introduced by this migration.
--
-- Preflight hashes freeze the observed live objects so concurrent out-of-band
-- changes fail closed instead of being silently normalized.
--
-- Expected live hashes at capture:
--   table:    aa6b38424a6e7dcaf6c2dad45094e9d6c56929a7c1a80c62aef45d18cbb54018
--   view:     17214d508ece399dd250252e3efaddbcb92d49f407b715c5604d7b5dd7406fe0
--   function: 2939fae3252aaf08367b5e5a28dbf01ee411981e09fd80a786fa188697f7c782
--   data:     71941b10ece0bb159fd05f77ec6c6848b100854705e627c28244541a58b0642e
--   rows:     54

begin;

do $preflight$
declare
  v_sha text;
  v_count integer;
begin
  if to_regclass('programacion.input_source_inventory_l1') is not null then
    with table_shape as (
      select jsonb_build_object(
        'comment',obj_description(c.oid,'pg_class'),
        'rls',c.relrowsecurity,
        'force_rls',c.relforcerowsecurity,
        'columns',(
          select jsonb_agg(jsonb_build_object(
            'name',a.attname,
            'type',pg_catalog.format_type(a.atttypid,a.atttypmod),
            'not_null',a.attnotnull,
            'default',pg_get_expr(ad.adbin,ad.adrelid)
          ) order by a.attnum)
          from pg_attribute a
          left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum
          where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped
        ),
        'constraints',(
          select jsonb_agg(
            jsonb_build_object('name',con.conname,'def',pg_get_constraintdef(con.oid))
            order by con.conname
          )
          from pg_constraint con where con.conrelid=c.oid
        ),
        'indexes',(
          select jsonb_agg(
            jsonb_build_object('name',ic.relname,'def',pg_get_indexdef(i.indexrelid))
            order by ic.relname
          )
          from pg_index i
          join pg_class ic on ic.oid=i.indexrelid
          where i.indrelid=c.oid
        ),
        'policies',(
          select jsonb_agg(jsonb_build_object(
            'name',pol.polname,
            'permissive',pol.polpermissive,
            'cmd',pol.polcmd,
            'roles',(
              select jsonb_agg(r.rolname order by r.rolname)
              from unnest(pol.polroles) x(oid)
              join pg_roles r on r.oid=x.oid
            ),
            'qual',pg_get_expr(pol.polqual,pol.polrelid),
            'with_check',pg_get_expr(pol.polwithcheck,pol.polrelid)
          ) order by pol.polname)
          from pg_policy pol where pol.polrelid=c.oid
        ),
        'grants',(
          select jsonb_agg(
            jsonb_build_object('grantee',grantee,'privilege',privilege_type)
            order by grantee,privilege_type
          )
          from information_schema.role_table_grants
          where table_schema='programacion'
            and table_name='input_source_inventory_l1'
        )
      ) shape
      from pg_class c
      join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='programacion'
        and c.relname='input_source_inventory_l1'
    )
    select encode(
      extensions.digest(convert_to(shape::text,'UTF8'),'sha256'),'hex'
    ) into v_sha
    from table_shape;

    if v_sha <> 'aa6b38424a6e7dcaf6c2dad45094e9d6c56929a7c1a80c62aef45d18cbb54018' then
      raise exception 'INPUT_SOURCE_INVENTORY_TABLE_PREFLIGHT_DRIFT:%',v_sha;
    end if;

    select count(*) into v_count
    from programacion.input_source_inventory_l1;

    if v_count > 0 then
      select encode(
        extensions.digest(
          convert_to(
            (select jsonb_agg(to_jsonb(i) order by source_ref)
             from programacion.input_source_inventory_l1 i)::text,
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      ) into v_sha;

      if v_count <> 54
         or v_sha <> '71941b10ece0bb159fd05f77ec6c6848b100854705e627c28244541a58b0642e' then
        raise exception 'INPUT_SOURCE_INVENTORY_DATA_PREFLIGHT_DRIFT:count=%,sha=%',v_count,v_sha;
      end if;
    end if;
  end if;

  if to_regclass('programacion.v_input_source_inventory_l1_v1') is not null then
    with view_shape as (
      select jsonb_build_object(
        'comment',obj_description(c.oid,'pg_class'),
        'definition',pg_get_viewdef(c.oid,true),
        'options',c.reloptions,
        'grants',(
          select jsonb_agg(
            jsonb_build_object('grantee',grantee,'privilege',privilege_type)
            order by grantee,privilege_type
          )
          from information_schema.role_table_grants
          where table_schema='programacion'
            and table_name='v_input_source_inventory_l1_v1'
        )
      ) shape
      from pg_class c
      join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='programacion'
        and c.relname='v_input_source_inventory_l1_v1'
    )
    select encode(
      extensions.digest(convert_to(shape::text,'UTF8'),'sha256'),'hex'
    ) into v_sha
    from view_shape;

    if v_sha <> '17214d508ece399dd250252e3efaddbcb92d49f407b715c5604d7b5dd7406fe0' then
      raise exception 'INPUT_SOURCE_INVENTORY_VIEW_PREFLIGHT_DRIFT:%',v_sha;
    end if;
  end if;

  if to_regprocedure('programacion.fn_input_source_inventory_lookup_l1_v1(text)') is not null then
    with fn_shape as (
      select jsonb_build_object(
        'definition',pg_get_functiondef(p.oid),
        'acl',p.proacl::text
      ) shape
      from pg_proc p
      join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='programacion'
        and p.proname='fn_input_source_inventory_lookup_l1_v1'
    )
    select encode(
      extensions.digest(convert_to(shape::text,'UTF8'),'sha256'),'hex'
    ) into v_sha
    from fn_shape;

    if v_sha <> '2939fae3252aaf08367b5e5a28dbf01ee411981e09fd80a786fa188697f7c782' then
      raise exception 'INPUT_SOURCE_INVENTORY_FUNCTION_PREFLIGHT_DRIFT:%',v_sha;
    end if;
  end if;
end
$preflight$;

create table if not exists programacion.input_source_inventory_l1 (
  source_ref text primary key,
  schema_name text not null,
  table_name text not null,
  source_kind text not null
    check (source_kind in ('CANONICAL_TABLE','CANONICAL_SCOPED_TABLE')),
  source_scope text not null default 'FULL_TABLE',
  is_canonical boolean not null default true,
  snapshot_count bigint,
  current_count_cached bigint,
  reconciliation_state text not null,
  primary_key_columns text[] not null default '{}'::text[],
  column_names text[] not null default '{}'::text[],
  indexed_columns text[] not null default '{}'::text[],
  foreign_keys jsonb not null default '[]'::jsonb,
  query_tags text[] not null default '{}'::text[],
  query_hints jsonb not null default '{}'::jsonb,
  snapshot_source text,
  snapshot_captured_at timestamptz,
  last_reconciled_at timestamptz not null default now(),
  metadata jsonb not null default '{}'::jsonb,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(schema_name,table_name,source_scope)
);

comment on table programacion.input_source_inventory_l1 is
'Input Governance L1 discovery index of canonical Supabase sources. Stores schema metadata and cached counts only; canonical business rows remain in their original tables.';

alter table programacion.input_source_inventory_l1 enable row level security;

drop policy if exists p_input_source_inventory_l1_read
  on programacion.input_source_inventory_l1;

create policy p_input_source_inventory_l1_read
on programacion.input_source_inventory_l1
for select
to programacion_auditor,
   programacion_builder,
   programacion_human_authority,
   programacion_verifier
using (true);

revoke all on table programacion.input_source_inventory_l1 from public;
grant select on programacion.input_source_inventory_l1
to programacion_auditor,
   programacion_builder,
   programacion_human_authority,
   programacion_verifier;

create index if not exists input_source_inventory_l1_schema_table_idx
  on programacion.input_source_inventory_l1(schema_name,table_name);

create index if not exists input_source_inventory_l1_tags_gin
  on programacion.input_source_inventory_l1 using gin(query_tags);

create index if not exists input_source_inventory_l1_columns_gin
  on programacion.input_source_inventory_l1 using gin(column_names);

create or replace view programacion.v_input_source_inventory_l1_v1
with (security_invoker = true)
as
select
  source_ref,
  schema_name,
  table_name,
  source_kind,
  source_scope,
  snapshot_count,
  current_count_cached,
  current_count_cached - snapshot_count as row_delta_from_drive_snapshot,
  reconciliation_state,
  primary_key_columns,
  column_names,
  indexed_columns,
  foreign_keys,
  query_tags,
  query_hints,
  snapshot_source,
  snapshot_captured_at,
  last_reconciled_at,
  metadata
from programacion.input_source_inventory_l1
where active;

comment on view programacion.v_input_source_inventory_l1_v1 is
'L1 read-only projection for fast Input Governance source discovery. Discovery index only; not a replacement for canonical source tables.';

revoke all on table programacion.v_input_source_inventory_l1_v1 from public;
grant select on programacion.v_input_source_inventory_l1_v1
to programacion_auditor,
   programacion_builder,
   programacion_human_authority,
   programacion_verifier;

create or replace function programacion.fn_input_source_inventory_lookup_l1_v1(
  p_term text default null
)
returns table(
  source_ref text,
  reconciliation_state text,
  primary_key_columns text[],
  indexed_columns text[],
  matching_columns text[],
  query_tags text[],
  current_count_cached bigint
)
language sql
stable
security invoker
set search_path = programacion, pg_catalog
as $function$
  with mode as (
    select exists(
      select 1
      from programacion.input_source_inventory_l1 z
      where z.active
        and (
          lower(z.source_ref)=lower(p_term)
          or exists(select 1 from unnest(z.query_tags) t where lower(t)=lower(p_term))
          or exists(select 1 from unnest(z.column_names) c where lower(c)=lower(p_term))
        )
    ) structured_match
  )
  select
    i.source_ref,
    i.reconciliation_state,
    i.primary_key_columns,
    i.indexed_columns,
    coalesce((
      select array_agg(c order by c)
      from unnest(i.column_names) c
      where p_term is not null and lower(c)=lower(p_term)
    ),'{}'::text[]) as matching_columns,
    i.query_tags,
    i.current_count_cached
  from programacion.input_source_inventory_l1 i
  cross join mode m
  where i.active
    and (
      p_term is null
      or lower(i.source_ref)=lower(p_term)
      or exists(select 1 from unnest(i.query_tags) t where lower(t)=lower(p_term))
      or exists(select 1 from unnest(i.column_names) c where lower(c)=lower(p_term))
      or (not m.structured_match and i.source_ref ilike '%'||p_term||'%')
    )
  order by
    case
      when p_term is not null and lower(i.source_ref)=lower(p_term) then 0
      when p_term is not null and exists(select 1 from unnest(i.query_tags) t where lower(t)=lower(p_term)) then 1
      when p_term is not null and exists(select 1 from unnest(i.column_names) c where lower(c)=lower(p_term)) then 2
      else 3
    end,
    i.source_ref;
$function$;

revoke all on function programacion.fn_input_source_inventory_lookup_l1_v1(text)
from public;

grant execute on function programacion.fn_input_source_inventory_lookup_l1_v1(text)
to programacion_auditor,
   programacion_builder,
   programacion_human_authority,
   programacion_verifier;

